function lengthOfLIS(nums) {
    const sub = [];
    for (const x of nums) {
        let l = 0, r = sub.length;
        while (l < r) {
            const mid = Math.floor((l + r) / 2);
            if (sub[mid] < x) l = mid + 1;
            else r = mid;
        }
        if (l < sub.length) sub[l] = x;
        else sub.push(x);
    }
    return sub.length;
}
